"""Create a portable, explicitly marked demo project from the packaged R4 source."""
import argparse,json,re,shutil
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--destination',required=True,type=Path);p.add_argument('--name',required=True);p.add_argument('--mode',choices=['original','reference'],default='original');a=p.parse_args()
kit=Path(__file__).resolve().parents[1];source=kit/'assets/button-r4';target=a.destination.expanduser().resolve()
if not source.is_dir():p.error('Extract the complete ZIP first; assets/button-r4 is required.')
if target.exists():p.error('Destination already exists; choose a new folder. Nothing was overwritten.')
slug=re.sub(r'[^a-z0-9]+','-',a.name.lower()).strip('-') or 'new-animation'
shutil.copytree(source,target,ignore=shutil.ignore_patterns('node_modules','production','__pycache__','.qa','qa','REPORT.md','README.md','AGENTS.md'))
(target/'qa').mkdir();shutil.copy2(source/'qa/character-provenance.json',target/'qa/character-provenance.json')
(target/'production').mkdir();(target/'Vídeos').mkdir()
(target/'.gitignore').write_text((target/'.gitignore').read_text()+'production/\n')
config={'name':a.name,'slug':slug,'mode':a.mode,'language':'en','containsExampleChoreography':True,'storyAuthority':'Replace the R4 demonstration with the current user story; reference characters do not imply reference screenplay.','fps':60,'width':1920,'parallelism':2,'output':{'directory':'Vídeos','filename':slug+'-complete.mp4'},'mechanismWindows':[],'silenceWindows':[]}
(target/'project-config.json').write_text(json.dumps(config,indent=2)+'\n')
shutil.copy2(kit/'templates/brief.md',target/'BRIEF.md');shutil.copy2(kit/'templates/requirements.txt',target/'requirements.txt')
(target/'AGENTS.md').write_text('''# New animation project\n\nRead BRIEF.md and project-config.json. The initial story and bindings are an explicitly marked R4 demo; write the requested screenplay and acting rather than delivering this example as a new film. Preserve the five original character files listed in qa/character-provenance.json unless the user authorizes character changes. New story code determines duration/cast/chapters; do not speed up or pad the example to hit a target. Use explicit supports, continuous contacts and fixed-step physics. Only completed full-film MP4 exports belong in Vídeos. Keep parts, previews, README, JSON and audio outside it. Default visible text is English; follow the current user's language instructions. Preserve older revisions, never include secrets, and do not claim new API generation or human playback/listening without evidence. Confirm authorized publication and always link the actual output folder for complete exports.\n''')
# Infrastructure is adapted here; archived example assets remain byte-identical in the kit.
f=target/'render.mjs';s=f.read_text().replace("executablePath:'/usr/bin/chromium'","executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium'");f.write_text(s)
f=target/'scripts/inspect.mjs';s=f.read_text();s="import{resolve}from'node:path';\n"+s;s=s.replace("const out='/workspace/animation-production-r4'","const out=resolve(root,'production')")
s=s.replace('frames:9000','frames:Math.round(S.duration*60)').replace('i<9000','i<Math.round(S.duration*60)').replace('a<3','a<S.names.length').replace('z<3','z<S.names.length').replace('for(const t of[25,50,75,100,125])','for(const t of S.chapters.slice(1).map(c=>c.start))')
s=re.sub(r'const times=\[[^\n]*\];',"const times=await b.page.evaluate(()=>StoryV6.chapters.flatMap(c=>[.1,.3,.5,.7,.9].map(u=>c.start+(c.end-c.start)*u)));",s)
s=s.replace("import{mkdir,writeFile}","import{mkdir,writeFile,readFile}")
s=s.replace("const out=resolve(root,'production')","const config=JSON.parse(await readFile(root+'/project-config.json','utf8'));const out=resolve(root,'production')")
s=s.replace('b.page.evaluate(()=>{const S=','b.page.evaluate(({fps})=>{const FPS=fps,S=').replace('return r;});','return r;},{fps:config.fps});').replace('fps:60','fps:FPS').replace('S.duration*60','S.duration*FPS').replace('i/60','i/FPS').replace('+=1/60','+=1/FPS').replace('maxJointStep<25','maxJointStep<25*60/config.fps')
s=s.replace('...StoryV6.propImpacts].sort','...StoryV6.propImpacts].filter(e=>e.t>=0&&e.t<StoryV6.duration).sort')
f.write_text(s)
f=target/'score.py';s=f.read_text();s=s.replace('ROOT=Path(__file__).resolve().parent;SR=48000;DURATION=150',"ROOT=Path(__file__).resolve().parent;SR=48000\nmeta=json.loads((ROOT/'qa/story.json').read_text());DURATION=float(meta['duration']);config=json.loads((ROOT/'project-config.json').read_text())")
s=s.replace('SR*DURATION,2','round(SR*DURATION),2').replace('for ch in range(6):','for ch,chapter in enumerate(meta[\'chapters\']):').replace('beat=60/bpms[ch];start=ch*25',"beat=60/bpms[ch%len(bpms)];start=chapter['start'];chapter_duration=chapter['end']-chapter['start']")
s=s.replace('0,24.85,','0,max(0,chapter_duration-.15),').replace('if ch==5 and 18.5<t<20:continue','if False:continue').replace('roots[ch]','roots[ch%len(roots)]').replace('np.arange(0,25,beat*4)','np.arange(0,chapter_duration,beat*4)').replace('min(beat*4,25-bar)','min(beat*4,chapter_duration-bar)')
s=s.replace('[(22,68.5,110,.009),(83.4,127.4,143,.012)]',"config.get('mechanismWindows',[])").replace('[(140.7,142.4)]',"config.get('silenceWindows',[])")
s=s.replace("Path('/workspace/animation-production-r4/audio-master.wav')","(ROOT/'production/audio-master.wav')").replace("Path('/workspace/animation-production-r4/audio-master-decoded.wav')","(ROOT/'production/audio-master-decoded.wav')")
s=s.replace('six instrumental chapters plus spatial event foley','instrumental chapters plus spatial event foley')
s=s.replace("'-t','150'","'-t',str(DURATION)").replace("'duration':150","'duration':DURATION").replace('new Forbidden Button 150s cues','the current story cues').replace('No new API request made for R4;','No new API request made by this template;');f.write_text(s)
f=target/'scripts/http-files.mjs';s=f.read_text();s="import{readFileSync}from'node:fs';\n"+s;s=s.replace("resolve(root,'../../Vídeos/The-Forbidden-Button-R4-1080p60.mp4')","(()=>{const cfg=JSON.parse(readFileSync(resolve(root,'project-config.json'),'utf8'));return resolve(root,cfg.output.directory,cfg.output.filename);})()")
f.write_text(s)
for name in ['render-parts.mjs','assemble.mjs','check-player.mjs','verify-character-files.py','review-encoded.py']:
 shutil.copy2(kit/'templates'/name,target/'scripts'/name)
f=target/'src/player.js';s=f.read_text().replace('Math.min(150,t)','Math.min(film.duration,t)').replace('position>=150','position>=film.duration').replace(' / 2:30',' / ${fmt(film.duration)}');s=s.replace("let running=false", "document.querySelector('#seek').max=film.duration;let running=false");f.write_text(s)
(target/'video.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Full film</title><link rel="stylesheet" href="style.css"><body><main><h1 id="title">Full film</h1><video controls id="video" preload="metadata" src="delivery/full.mp4"></video><nav id="chapters"></nav><p><a href="index.html">Code player</a> · <a href="delivery/full.mp4" download>Download full film</a></p></main><script>Promise.all([fetch('project-config.json').then(r=>r.json()),fetch('qa/story.json').then(r=>r.json())]).then(([cfg,story])=>{document.title=cfg.name;document.querySelector('#title').textContent=cfg.name;for(const c of story.chapters){const b=document.createElement('button');b.textContent=c.title;b.onclick=()=>document.querySelector('video').currentTime=c.start;document.querySelector('nav').append(b);}});</script></body></html>''')
d=json.loads((target/'package.json').read_text());d['name']=slug;d['scripts']['test']='python3 scripts/verify-character-files.py && node scripts/inspect.mjs --verify';d['scripts']['score']='python3 score.py';d['scripts']['render:parts']='node scripts/render-parts.mjs';d['scripts']['assemble']='node scripts/assemble.mjs';d['scripts']['check:player']='node scripts/check-player.mjs';(target/'package.json').write_text(json.dumps(d,indent=2)+'\n');lock=json.loads((target/'package-lock.json').read_text());lock['name']=slug;lock['packages']['']['name']=slug;(target/'package-lock.json').write_text(json.dumps(lock,indent=2)+'\n')
(target/'README.md').write_text('''# Animation starter\n\nThis project still contains the explicitly marked R4 demonstration story. Read BRIEF.md, write the requested story/acting, and update project-config.json before calling it a new film. Changing a target duration in a brief does not retime the example. The unchanged character files are verified by hash.\n\nInstall Node >=22, Chromium and FFmpeg/FFprobe. Run npm ci. Create a Python venv and install requirements.txt; select its Python when running score.py. CHROMIUM_PATH can point to the installed Chromium.\n\n1. npm test\n2. Copy production/story.json to qa/story.json\n3. python3 score.py\n4. npm run render:parts\n5. npm run assemble\n6. npm run check:player\n7. python3 scripts/review-encoded.py\n\nThe inspection and render infrastructure derive duration and chapter boundaries from StoryV6; output size/FPS/parallelism come from project-config.json. The renderer supports 24, 30 or 60fps and a 16:9 viewport. The story, performance bindings and world remain authored code requiring adaptation.\n\nOnly completed full-film MP4 files belong in Vídeos. Temporary renders go to production/parts and validation to qa/exports. npm run serve opens the code/video players with a single-file output alias.\n''')
print(json.dumps({'created':str(target),'mode':a.mode,'containsExampleChoreography':True,'next':'Read BRIEF.md; implement the requested screenplay and acting before producing a new film.'}))
